import{_ as t,o as i,c as h,a5 as o}from"./chunks/framework.Bf1r8NYr.js";const d=JSON.parse('{"title":"Bài 4 — Chất lượng dữ liệu, dữ liệu khuyết và tái lập","description":"","frontmatter":{},"headers":[],"relativePath":"course/module-4-quality/index.md","filePath":"course/module-4-quality/index.md"}'),u={name:"course/module-4-quality/index.md"};function c(l,n,a,g,e,r){return i(),h("div",null,[...n[0]||(n[0]=[o('<h1 id="bai-4-—-chat-luong-du-lieu-du-lieu-khuyet-va-tai-lap" tabindex="-1">Bài 4 — Chất lượng dữ liệu, dữ liệu khuyết và tái lập <a class="header-anchor" href="#bai-4-—-chat-luong-du-lieu-du-lieu-khuyet-va-tai-lap" aria-label="Permalink to &quot;Bài 4 — Chất lượng dữ liệu, dữ liệu khuyết và tái lập&quot;">​</a></h1><p><strong>Mục tiêu:</strong> đánh giá được chất lượng dữ liệu theo 5 chiều; xử lý đúng dữ liệu khuyết.</p><h2 id="noi-dung-chinh" tabindex="-1">Nội dung chính <a class="header-anchor" href="#noi-dung-chinh" aria-label="Permalink to &quot;Nội dung chính&quot;">​</a></h2><p>Lớp kiểm soát bảo mật, đạo đức và pháp lý áp dụng xuyên suốt mọi giai đoạn của vòng đời dữ liệu.</p><p>Dữ liệu EHR tái sử dụng cho nghiên cứu thường bẩn theo những cách có hệ thống. Khung của Weiskopf &amp; Weng (2013) đánh giá chất lượng theo 5 chiều: <strong>completeness (đầy đủ), correctness (đúng), concordance (nhất quán giữa các nguồn), plausibility (hợp lý), currency (cập nhật)</strong>. Khung hài hòa của Kahn và cộng sự (2016) <strong>[CẦN KIỂM CHỨNG thư mục]</strong> bổ sung phân biệt <strong>verification</strong> (dữ liệu có đúng định dạng và quy tắc không) và <strong>validation</strong> (dữ liệu có đúng với thực tế không).</p><p>Dữ liệu khuyết không phải một loại. Theo Rubin (1976):</p><ul><li><strong>MCAR (Missing Completely At Random):</strong> khuyết hoàn toàn ngẫu nhiên — ít gây chệch nhất.</li><li><strong>MAR (Missing At Random):</strong> khuyết có thể dự đoán được từ dữ liệu đã quan sát — dùng được multiple imputation.</li><li><strong>MNAR (Missing Not At Random):</strong> khuyết liên quan đến chính giá trị bị khuyết — không thể phân biệt được từ dữ liệu, cần phân tích độ nhạy.</li></ul><p>Quy tắc thực hành (Sterne và cộng sự, 2009): <strong>multiple imputation là cách khuyến nghị khi MAR; không dùng mean imputation hay last observation carried forward</strong> vì chúng bóp méo phương sai và quan hệ giữa các biến. Mọi cách xử lý dữ liệu khuyết phải được ghi lại trong protocol phân tích trước khi nhìn kết quả.</p><p>Cuối cùng là tái lập: khảo sát của Baker (2016) trên 1.500 nhà khoa học cho thấy hơn 70% không tái lập được thí nghiệm của nhóm khác. Dữ liệu tốt mà không có code, phiên bản dữ liệu và môi trường phân tích đi kèm thì vẫn không tái lập được.</p><p><strong>Điểm cần nhớ:</strong> câu hỏi đầu tiên khi thấy dữ liệu khuyết không phải “điền gì vào?”, mà là “vì sao nó khuyết?”.</p>',10)])])}const p=t(u,[["render",c]]);export{d as __pageData,p as default};
